begin;
do $$
declare secret text=repeat('q',64);sid uuid=gen_random_uuid();tid uuid=gen_random_uuid();lease uuid;other uuid;result jsonb;blocked boolean;owner_jwt text;buyer_jwt text;buyer uuid;identity jsonb;room uuid;file uuid;ids uuid[];count_before bigint;
begin
 update ig_private.integration_root set secret_hash=encode(extensions.digest(secret,'sha256'),'hex');
 lease=public.ig_worker_health(secret,'{"action":"start","component":"email"}');assert lease is not null;
 assert public.ig_worker_health(secret,'{"action":"start","component":"email"}') is null,'Concurrent worker lease admitted';
 perform public.ig_worker_health(secret,jsonb_build_object('action','finish','component','email','lease',gen_random_uuid(),'ok',true));
 assert (select last_success is null from ig_private.worker_health where component='email'),'Wrong worker completed lease';
 perform public.ig_worker_health(secret,jsonb_build_object('action','finish','component','email','lease',lease,'ok',false));
 assert (select failures=1 and ok=false from ig_private.worker_health where component='email');
 lease=public.ig_worker_health(secret,'{"action":"start","component":"email"}');
 perform public.ig_worker_health(secret,jsonb_build_object('action','finish','component','email','lease',lease,'ok',true,'idle',true));
 assert (select failures=1 and ok=false and last_success is null from ig_private.worker_health where component='email'),'Idle queue hid a failure';
 lease=public.ig_worker_health(secret,'{"action":"start","component":"email"}');
 perform public.ig_worker_health(secret,jsonb_build_object('action','finish','component','email','lease',lease,'ok',true));
 assert (select failures=0 and ok=true and last_success is not null from ig_private.worker_health where component='email');
 perform public.ig_gullu_guest(secret,jsonb_build_object('action','start','session_id',sid,'name','Guest Example','email','synthetic@example.invalid','mobile','+919999000000','consent',true));
 perform public.ig_gullu_guest(secret,jsonb_build_object('action','record','session_id',sid,'turn_id',tid,'question','Hi','answer','Hello','sources','[]'::jsonb,'practice_interest','General enquiry','follow_up',false));
 result=public.ig_gullu_session(secret,jsonb_build_object('action','resume','session_id',sid));
 assert result->>'firstName'='Guest';assert result#>>'{messages,0,question}'='Hi';assert not result?'email' and not result?'mobile';
 perform public.ig_gullu_session(secret,jsonb_build_object('action','end','session_id',sid));
 assert public.ig_gullu_session(secret,jsonb_build_object('action','resume','session_id',sid)) is null;
 blocked=false;begin perform public.ig_gullu_guest(secret,jsonb_build_object('action','context','session_id',sid));exception when insufficient_privilege then blocked=true;end;assert blocked,'Ended chat still accessible';
 select u.id,jsonb_build_object('sub',u.id,'session_id',s.id,'role','authenticated','aal','aal1')::text into buyer,buyer_jwt from auth.users u join auth.sessions s on s.user_id=u.id where email='buyer@example.invalid';
 select jsonb_build_object('sub',u.id,'session_id',s.id,'role','authenticated','aal','aal2')::text into owner_jwt from auth.users u join auth.sessions s on s.user_id=u.id where email='owner@example.invalid';
 update public.ig_profiles set policy_version=ig_private.current_policy() where id=buyer;
 insert into public.ig_consents(user_id,purpose,granted,version,policy_hash) select buyer,'registration',true,version,sha256 from public.ig_policy_releases where current;
 perform set_config('request.jwt.claims',buyer_jwt,true);
 identity=public.ig_client_identity('{"action":"create","kind":"organisation","entity_type":"llp","registration_id":"ABC-1234","country":"IN","legal_name":"Example LLP","signer":"Example Signer","vital_date":"2020-01-01","consent":true}');
 assert (select country='IN' and registration_id='ABC-1234' and ig_private.kyc_slots(e)=array['registration','authority'] from public.ig_legal_entities e where id=(identity->>'id')::uuid);
 lease=public.ig_kyc_admit(jsonb_build_object('id',identity->>'id','revision',1,'slot','registration'));assert lease is not null;
 assert public.ig_kyc_admit(jsonb_build_object('id',identity->>'id','revision',1,'slot','authority')) is null;
 perform public.ig_kyc_admit(jsonb_build_object('action','release','lease',gen_random_uuid()));
 assert public.ig_kyc_admit(jsonb_build_object('id',identity->>'id','revision',1,'slot','authority')) is null,'Wrong lease released KYC';
 perform public.ig_kyc_admit(jsonb_build_object('action','release','lease',lease));
 assert public.ig_kyc_admit(jsonb_build_object('id',identity->>'id','revision',1,'slot','authority')) is not null;
 identity=public.ig_client_identity('{"action":"create","kind":"international_individual","country":"GB","legal_name":"Overseas Person","vital_date":"1985-01-01","id_method":"passport","consent":true}');
 assert (select signer='Overseas Person' and ig_private.kyc_slots(e)=array['passport'] from public.ig_legal_entities e where id=(identity->>'id')::uuid);
 identity=public.ig_client_identity('{"action":"create","kind":"company","legal_name":"Example Company","signer":"Example Signer","vital_date":"2020-01-01","cin":"U12345DL2020PLC123456","consent":true}');
 assert (select gstin is null and ig_private.kyc_slots(e)=array['incorporation','resolution'] from public.ig_legal_entities e where id=(identity->>'id')::uuid);
 perform set_config('request.jwt.claims',owner_jwt,true);
 insert into public.ig_content(kind,slug,title) values('project','audit-room-test','Synthetic project') returning id into other;
 insert into public.ig_data_rooms(content_id,title) values(other,'Synthetic room') returning id into room;
 insert into public.ig_room_files(room_id,name,object_key,mime,bytes,status,download_enabled) values(room,'Spreadsheet.xlsx','synthetic/audit','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',100,'ready',false) returning id into file;
 assert public.ig_room_readiness(jsonb_build_object('room_id',room))->>'ready'='false';
 update public.ig_room_files set download_enabled=true where id=file;
 assert public.ig_room_readiness(jsonb_build_object('room_id',room,'download_mode','all'))->>'ready'='true';
 assert public.ig_room_readiness(jsonb_build_object('room_id',room,'download_mode','none'))->>'ready'='false';
 assert ig_private.product_category('{"category":"Lighting"}','Dining table light','[]')='lighting';
 assert ig_private.product_category('{"category":"Crockery"}','Light blue plate','[]')='crockery';
 assert ig_private.product_category('{}','Steak knife','[]')='cutlery';
 assert ig_private.product_type('cutlery','{}','Steak knife')='Knives';
 result=public.ig_horeca_catalogue('{"category":"cutlery"}');assert jsonb_array_length(result->'items')<=24;
 assert (select file_size_limit=10000000 from storage.buckets where id='client-kyc');
end $$;
rollback;
